async test "tw defer runs on timeout" {
  let log = []
  let r : Int? = @async.with_timeout_opt(50, () => {
    defer log.push("defer")
    @async.sleep(500)
    1
  })
  assert_true(r is None)
  assert_eq(log, ["defer"])
}

