async test "all cancels sibling on failure" {
  let log = []
  let caught = try {
    let _ = @async.all([
      () => { @async.sleep(50); raise Failure::Failure("x") },
      () => {
        match @async.handle_cancellation(() => @async.sleep(1000)) {
          None => log.push("cancelled")
          Some(_) => log.push("done")
        }
        2
      },
    ])
    false
  } catch {
    _ => true
  }
  assert_true(caught)
  assert_eq(log, ["cancelled"])
}

